{"hypotheses": [
  {
    "name": "Customer-Driven Asset Expansion Anomaly",
    "mechanism": "Firms experiencing strong momentum among their major customers (iomom_cust) while simultaneously expanding their asset bases (AssetGrowth) may benefit from persistent demand-side synergies that individual signals miss. This composite exploits underappreciated positive feedback between supply-chain demand and firm-level reinvestment, which is less likely to be arbitraged due to its cross-firm complexity.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Organizational Capital Premium in Dispersed Forecasts",
    "mechanism": "Firms with high organizational capital (OrgCap) tend to outperform, but this effect is amplified when analyst forecast dispersion (ForecastDispersion) is high, indicating greater disagreement and thus greater mispricing opportunities. The composite exploits the fact that the market underweights intangible assets most when uncertainty is high.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "ForecastDispersion"},
        {"weight": -0.5, "primitive": "DelFINL"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Supplier-Driven Inventory Cycle Premium",
    "mechanism": "When momentum among key suppliers (iomom_supp) aligns with rising inventory growth (InvGrowth), it indicates synchronized upstream optimism. By offsetting with a short in AssetGrowth, this composite aims to capture inefficiencies in supply chain inventory cycles—especially as most investors lack ability to track such cross-firm signals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": 0.5, "primitive": "InvGrowth"},
        {"weight": -0.5, "primitive": "AssetGrowth"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_supp", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Earnings Uncertainty and Deferred Investment Edge",
    "mechanism": "Firms with high earnings forecast disparity (EarningsForecastDisparity) but low recent capex growth (grcapx) may be poised for mean reversion, as the market overreacts to uncertainty but underreacts to deferred investment. Including a short in RealizedVol further isolates this mispricing.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsForecastDisparity"},
        {"weight": 0.5, "primitive": "grcapx"},
        {"weight": -0.5, "primitive": "RealizedVol"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Share Repurchase Convexity under Low Volatility",
    "mechanism": "Firms engaging in share repurchases (ShareRepurchase) while exhibiting low Amihud illiquidity (Illiquidity) and low put-call volatility spread (CPVolSpread) benefit from temporary price support and liquidity-driven mispricing, especially when option-implied volatility is subdued.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 0.5, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "CPVolSpread"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "ShareRepurchase", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Employee Growth and Industry Concentration Shock",
    "mechanism": "Firms with rapid employment growth (hire) in industries experiencing increasing sales concentration (Herf) tend to capture market share and scale advantages. By including a short in AnalystRevision, the composite bets on real economic expansion over mere sentiment.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "hire"},
        {"weight": 0.5, "primitive": "Herf"},
        {"weight": -0.5, "primitive": "AnalystRevision"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.50,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Patent-Driven R&D Surprise Premium",
    "mechanism": "Firms with unexpectedly high R&D spending (SurpriseRD) and high patent-to-R&D ratios (PatentsRD) but low credit rating downgrade risk (CredRatDG) are likely to be underpriced due to market skepticism regarding intangible innovation. This composite isolates situations where innovation plausibly translates to value.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "SurpriseRD"},
        {"weight": 0.5, "primitive": "PatentsRD"},
        {"weight": -0.5, "primitive": "CredRatDG"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "SurpriseRD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "Governance-Driven Deferred Payout Premium",
    "mechanism": "Firms with high governance quality (Governance) but temporarily low payout yields (PayoutYield), when combined with low analyst optimism (AOP), reflect capital discipline not yet recognized by the market. The composite benefits from subsequent revaluation as disciplined governance leads to eventual payout normalization.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 0.5, "primitive": "PayoutYield"},
        {"weight": -0.5, "primitive": "AOP"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "Governance", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 32
  }
]}
